import React, { useState } from 'react';
import api from '../../../api/api';
import styles from './LoginScreen.module.css';
import logo from '../../../assets/images/logo.png';

const LoginScreen = ({ onLoginSuccess }) => {
  // Estado unificado para o identificador de login
  const [loginIdentifier, setLoginIdentifier] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  // Função inteligente para formatar o input
  const handleIdentifierChange = (e) => {
    let value = e.target.value;
    
    // Verifica se o input parece ser um número de telefone
    if (/^[0-9()-\s]*$/.test(value)) {
      let digitsOnly = value.replace(/\D/g, ''); // Remove tudo que não é dígito
      digitsOnly = digitsOnly.substring(0, 11); // Limita a 11 dígitos

      if (digitsOnly.length > 6) {
        value = digitsOnly.replace(/^(\d{2})(\d{5})(\d{0,4}).*/, '($1) $2-$3');
      } else if (digitsOnly.length > 2) {
        value = digitsOnly.replace(/^(\d{2})(\d{0,5}).*/, '($1) $2');
      } else if (digitsOnly.length > 0) {
        value = digitsOnly.replace(/^(\d*)/, '($1');
      } else {
        value = '';
      }
    }
    
    setLoginIdentifier(value);
  };

  const onSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const response = await api.post('/auth/login', { loginIdentifier, password });
      onLoginSuccess(response.data);
    } catch (err) {
      setError('Credenciais inválidas.');
      console.error("Erro no login:", err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={styles.container}>
      <div className={styles.loginBox}>
        <img src={logo} alt="Logo Selo Cidadania" className={styles.logo} />
        <h2>Entrar no Sistema</h2>
        <form onSubmit={onSubmit}>
          <div className={styles.inputGroup}>
            <label htmlFor="loginIdentifier">Email ou Telefone / WhatsApp</label>
            <input
              type="text"
              id="loginIdentifier"
              name="loginIdentifier"
              placeholder="Digite seu email ou telefone"
              value={loginIdentifier}
              onChange={handleIdentifierChange}
              required
            />
          </div>
          <div className={styles.inputGroup}>
            <label htmlFor="password">Senha</label>
            <input
              type="password"
              id="password"
              name="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>
          {error && <p className={styles.error}>{error}</p>}
          <button type="submit" className={styles.loginButton} disabled={loading}>
            {loading ? 'Aguarde...' : 'Entrar'}
          </button>
        </form>
      </div>
    </div>
  );
};

export default LoginScreen;
